  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 1, $q$Alphabet · Set 1: a, b, t, s, m$q$, $q$Connect the familiar sound to the new symbol. Point out what the mouth, tongue and teeth do. Have a visual for each letter. Model blending the sounds to make words, starting with VC and CV words and nonsense words. Make sure students know the difference between vowels and consonants.$q$, ARRAY[$q$letter sounds$q$, $q$blending$q$]::text[], ARRAY[$q$RF.K.1D$q$, $q$RF.K.3A$q$, $q$RF.K.2D$q$]::text[], 1, 'claude') RETURNING id INTO u;
