  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 7, $q$Closed Syllables · CVC & VC Words: Short a$q$, $q$CVC words are consonant-vowel-consonant; VC words are vowel-consonant. Focus on what the mouth is doing for each vowel sound. Use a keyword for each vowel. Teach decoding strategies: Touch and Say, reading onset and rime, successive blending. If needed, start with words that begin with consonants that stretch (f, l, m, n, r, s, v, z). Every syllable needs a vowel sound.$q$, ARRAY[$q$short a$q$, $q$cvc$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.K.3B$q$, $q$RF.1.2C$q$, $q$RF.1.3B$q$, $q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
