  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 19, $q$Closed Syllables · Morphology: Suffix -es$q$, $q$Words that end with the sounds /s/, /ch/, /z/ or /sh/ (s, x, z, sh, ch) use suffix -es instead of -s.$q$, ARRAY[$q$suffixes$q$]::text[], ARRAY[$q$RF.1.3F$q$, $q$L.1.4C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Suffix -es (dishes, buzzes).$q$, '', ARRAY[$q$RF.1.3F$q$, $q$L.1.4C$q$]::text[], ARRAY[$q$suffixes$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 20, $q$Closed Syllables · Beginning Blends$q$, $q$Consonant blends are two or more consonants next to each other that each keep their own sound, unlike digraphs, which represent one sound.$q$, ARRAY[$q$consonant blends$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.2B$q$, $q$RF.1.3B$q$, $q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Beginning Blends (step, frog, plum).$q$, '', ARRAY[$q$RF.1.2B$q$, $q$RF.1.3B$q$]::text[], ARRAY[$q$consonant blends$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: and, must, help, just, went, stop, best, next, jump, last, want, from$q$, $q$Students will read and spell the high-frequency words and, must, help, just, went, stop, best, next, jump, last, want, from by sight.$q$, '', ARRAY[$q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 21, $q$Closed Syllables · Ending Blends$q$, $q$Consonant blends are two or more consonants next to each other that each keep their own sound, unlike digraphs, which represent one sound.$q$, ARRAY[$q$consonant blends$q$]::text[], ARRAY[$q$RF.1.2B$q$, $q$RF.1.3B$q$]::text[], 1, 'claude') RETURNING id INTO u;
