  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 22, $q$Closed Syllables · Review Together$q$, $q$Time to practise to automaticity. Duration will vary.$q$, ARRAY[$q$cvc$q$, $q$consonant digraphs$q$, $q$consonant blends$q$, $q$fluency$q$]::text[], ARRAY[$q$RF.1.3B$q$, $q$RF.1.4B$q$]::text[], 1, 'claude') RETURNING id INTO u;
