  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 23, $q$Closed Syllables · Morphology: Suffix -ed$q$, $q$Suffix -ed can make three sounds: /t/, /d/ and /id/. Added to a base word, it makes the past tense.$q$, ARRAY[$q$suffixes$q$]::text[], ARRAY[$q$RF.1.3F$q$, $q$L.1.4C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Suffix -ed (jumped, rested).$q$, '', ARRAY[$q$RF.1.3F$q$, $q$L.1.4C$q$]::text[], ARRAY[$q$suffixes$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 24, $q$Closed Syllables · Double Consonants: ll, ff, ss, zz$q$, $q$Rule: when a one-syllable word ends with a short vowel followed by f, l, s or z, double that consonant.$q$, ARRAY[$q$spelling rules$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3B$q$, $q$L.1.2D$q$, $q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
