  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: will, off, well, full, pull$q$, $q$Students will read and spell the high-frequency words will, off, well, full, pull by sight.$q$, '', ARRAY[$q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 25, $q$Closed Syllables · Consonant Digraphs: ck$q$, $q$Rule: when a one-syllable word ends with a short vowel followed by the /k/ sound, use ck. Otherwise use k.$q$, ARRAY[$q$consonant digraphs$q$, $q$spelling rules$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3A$q$, $q$L.1.2D$q$, $q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Consonant Digraphs: ck (rock, sack).$q$, '', ARRAY[$q$RF.1.3A$q$, $q$L.1.2D$q$]::text[], ARRAY[$q$consonant digraphs$q$, $q$spelling rules$q$]::text[], 'claude');
