  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 26, $q$Closed Syllables · Consonant Digraphs: tch$q$, $q$Rule: when a word ends with a short vowel followed by the /ch/ sound, use tch. Otherwise use ch.$q$, ARRAY[$q$consonant digraphs$q$, $q$spelling rules$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3A$q$, $q$L.1.2D$q$, $q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
