  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: watch$q$, $q$Students will read and spell the high-frequency words watch by sight.$q$, '', ARRAY[$q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 27, $q$Closed Syllables · Morphology: Suffix -ing$q$, $q$Suffix -ing means it is happening right now.$q$, ARRAY[$q$suffixes$q$]::text[], ARRAY[$q$RF.1.3F$q$, $q$L.1.4C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Suffix -ing (jumping).$q$, '', ARRAY[$q$RF.1.3F$q$, $q$L.1.4C$q$]::text[], ARRAY[$q$suffixes$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 28, $q$Closed Syllables · Exceptions: ild, old, ost, ind, olt$q$, $q$These syllables are closed, but the vowel does not make the expected short sound: ild, old, ost, ind, olt all have long vowel sounds.$q$, ARRAY[$q$long vowel exceptions$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3F$q$, $q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Exceptions: ild, old, ost, ind, olt (kind, fold, wild, most).$q$, '', ARRAY[$q$RF.1.3C$q$, $q$RF.2.3F$q$]::text[], ARRAY[$q$long vowel exceptions$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: old, cold, find, kind, hold, mind$q$, $q$Students will read and spell the high-frequency words old, cold, find, kind, hold, mind by sight.$q$, '', ARRAY[$q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 29, $q$Closed Syllables · -ng and -nk (& new grapheme: ng)$q$, $q$ing/ink makes the /ĭ/ sound; ang/ank has the /ă/ sound.$q$, ARRAY[$q$consonant digraphs$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3A$q$, $q$RF.1.3B$q$, $q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
