  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: bring, thing, think, thank, drink, sing, long$q$, $q$Students will read and spell the high-frequency words bring, thing, think, thank, drink, sing, long by sight.$q$, '', ARRAY[$q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 30, $q$Closed Syllables · <all> spells /ŏl/$q$, $q$When you hear /ŏl/ at the end of a word, you will usually spell it all. Exception: doll.$q$, ARRAY[$q$spelling rules$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3B$q$, $q$L.1.2D$q$, $q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern <all> spells /ŏl/ (ball, call).$q$, '', ARRAY[$q$RF.1.3B$q$, $q$L.1.2D$q$]::text[], ARRAY[$q$spelling rules$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: all, fall, small, call$q$, $q$Students will read and spell the high-frequency words all, fall, small, call by sight.$q$, '', ARRAY[$q$RF.K.3C$q$, $q$RF.1.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 31, $q$Closed Syllables · Beginning /k/ spelling rule$q$, $q$Rule: use k if e, i or y follows; otherwise use c.$q$, ARRAY[$q$spelling rules$q$]::text[], ARRAY[$q$L.1.2D$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Beginning /k/ spelling rule (camp, cost, kit, kelp).$q$, '', ARRAY[$q$L.1.2D$q$]::text[], ARRAY[$q$spelling rules$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 32, $q$Closed Syllables · Digraph & Triple Blends (str, spr, spl, scr)$q$, $q$Closed Syllables.$q$, ARRAY[$q$consonant blends$q$]::text[], ARRAY[$q$RF.1.2B$q$, $q$RF.1.3B$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Digraph & Triple Blends (str, spr, spl, scr) (shrub, splash, string).$q$, '', ARRAY[$q$RF.1.2B$q$, $q$RF.1.3B$q$]::text[], ARRAY[$q$consonant blends$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 33, $q$Closed Syllables · Morphology Rule: Doubling Rule$q$, $q$Rule: when a one-syllable word has one vowel followed by one consonant, double that consonant before adding a vowel suffix.$q$, ARRAY[$q$suffixes$q$, $q$spelling rules$q$]::text[], ARRAY[$q$RF.2.3E$q$, $q$L.2.2D$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology Rule: Doubling Rule (rubbed, hopping).$q$, '', ARRAY[$q$RF.2.3E$q$, $q$L.2.2D$q$]::text[], ARRAY[$q$suffixes$q$, $q$spelling rules$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 34, $q$Open Syllables · One-syllable Open$q$, $q$Syllables that end with a vowel. The vowel sound is long.$q$, ARRAY[$q$syllables$q$, $q$open syllables$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3D$q$, $q$RF.1.3E$q$, $q$RF.2.3A$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern One-syllable Open (me, we, baby, robot).$q$, '', ARRAY[$q$RF.1.3D$q$, $q$RF.1.3E$q$, $q$RF.2.3A$q$]::text[], ARRAY[$q$syllables$q$, $q$open syllables$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: he, me, be, we, go, no, so, she; irregular: do, to$q$, $q$Students will read and spell the high-frequency words he, me, be, we, go, no, so, she; irregular: do, to by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 35, $q$Open Syllables · Y as a vowel (long i)$q$, $q$Rule: English words do not end with the letter i. If you hear the sound /ī/ at the end of a word, usually use y.$q$, ARRAY[$q$long i igh y$q$, $q$open syllables$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$L.1.2D$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Y as a vowel (long i) (by, my, try, cry).$q$, '', ARRAY[$q$RF.1.3C$q$, $q$L.1.2D$q$]::text[], ARRAY[$q$long i igh y$q$, $q$open syllables$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: my, by, why$q$, $q$Students will read and spell the high-frequency words my, by, why by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 36, $q$Open Syllables · Morphology: Drop the y, make it an i$q$, $q$When a word ends with a consonant then y, drop the y and change it to i before adding suffixes, except -ing.$q$, ARRAY[$q$suffixes$q$, $q$spelling rules$q$]::text[], ARRAY[$q$RF.2.3E$q$, $q$L.2.2D$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Drop the y, make it an i (tries, flies).$q$, '', ARRAY[$q$RF.2.3E$q$, $q$L.2.2D$q$]::text[], ARRAY[$q$suffixes$q$, $q$spelling rules$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 37, $q$Silent e · VCe Pattern: a_e$q$, $q$VCe pattern: vowel-consonant-e. The first vowel says its name and the e is silent. This is one of silent e’s six jobs: it also makes c say /s/ and g say /j/, keeps words from ending in v, keeps a word from looking plural (house), and gives a syllable a written vowel (consonant -le).$q$, ARRAY[$q$long a vce$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern VCe Pattern: a_e (cake, game).$q$, '', ARRAY[$q$RF.1.3C$q$]::text[], ARRAY[$q$long a vce$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: make, made, gave, take, came, ate$q$, $q$Students will read and spell the high-frequency words make, made, gave, take, came, ate by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 38, $q$Silent e · VCe Pattern: i_e$q$, $q$VCe pattern: vowel-consonant-e. The first vowel says its name and the e is silent. This is one of silent e’s six jobs: it also makes c say /s/ and g say /j/, keeps words from ending in v, keeps a word from looking plural (house), and gives a syllable a written vowel (consonant -le).$q$, ARRAY[$q$long i vce$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern VCe Pattern: i_e (fine, smile).$q$, '', ARRAY[$q$RF.1.3C$q$]::text[], ARRAY[$q$long i vce$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: like, five, time, ride, white, live$q$, $q$Students will read and spell the high-frequency words like, five, time, ride, white, live by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 39, $q$Silent e · VCe Pattern: o_e$q$, $q$VCe pattern: vowel-consonant-e. The first vowel says its name and the e is silent. This is one of silent e’s six jobs: it also makes c say /s/ and g say /j/, keeps words from ending in v, keeps a word from looking plural (house), and gives a syllable a written vowel (consonant -le).$q$, ARRAY[$q$long o vce$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern VCe Pattern: o_e (mole, home).$q$, '', ARRAY[$q$RF.1.3C$q$]::text[], ARRAY[$q$long o vce$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: those, more, move, one, done, some, come$q$, $q$Students will read and spell the high-frequency words those, more, move, one, done, some, come by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 40, $q$Silent e · VCe Pattern: u_e$q$, $q$VCe pattern: vowel-consonant-e. The first vowel says its name and the e is silent. This is one of silent e’s six jobs: it also makes c say /s/ and g say /j/, keeps words from ending in v, keeps a word from looking plural (house), and gives a syllable a written vowel (consonant -le).$q$, ARRAY[$q$long u vce$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern VCe Pattern: u_e (cube, mule).$q$, '', ARRAY[$q$RF.1.3C$q$]::text[], ARRAY[$q$long u vce$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: here, these, where, there$q$, $q$Students will read and spell the high-frequency words here, these, where, there by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 41, $q$Silent e · VCe Pattern: Review all together$q$, $q$Time to practise to automaticity. Duration will vary.$q$, ARRAY[$q$long a vce$q$, $q$long i vce$q$, $q$long o vce$q$, $q$long u vce$q$, $q$fluency$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3B$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern VCe Pattern: Review all together.$q$, '', ARRAY[$q$RF.1.3C$q$, $q$RF.2.3B$q$]::text[], ARRAY[$q$long a vce$q$, $q$long i vce$q$, $q$long o vce$q$, $q$long u vce$q$, $q$fluency$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 42, $q$Silent e · <ce>$q$, $q$Silent e makes c say /s/ when e, i or y follows.$q$, ARRAY[$q$soft c and g$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3F$q$, $q$L.2.2D$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern <ce> (race, mice, chance).$q$, '', ARRAY[$q$RF.2.3F$q$, $q$L.2.2D$q$]::text[], ARRAY[$q$soft c and g$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: place, chance, once$q$, $q$Students will read and spell the high-frequency words place, chance, once by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 43, $q$Silent e · <ge> and <dge> spelling rule$q$, $q$Silent e makes g say /j/. When a word ends with /j/ right after a short vowel, use dge; otherwise ge.$q$, ARRAY[$q$soft c and g$q$, $q$spelling rules$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3F$q$, $q$L.2.2D$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern <ge> and <dge> spelling rule (page, hinge, bridge).$q$, '', ARRAY[$q$RF.2.3F$q$, $q$L.2.2D$q$]::text[], ARRAY[$q$soft c and g$q$, $q$spelling rules$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: change$q$, $q$Students will read and spell the high-frequency words change by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 44, $q$Silent e · <ve>$q$, $q$English words do not end in v: a word that ends with the sound /v/ gets a silent e after it.$q$, ARRAY[$q$spelling rules$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3F$q$, $q$L.2.2D$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern <ve> (give, have, valve).$q$, '', ARRAY[$q$RF.2.3F$q$, $q$L.2.2D$q$]::text[], ARRAY[$q$spelling rules$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: have, give, live$q$, $q$Students will read and spell the high-frequency words have, give, live by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 45, $q$Silent e · Morphology: Silent e with suffixes$q$, $q$Dropping rule: when adding a vowel suffix to a silent e word, drop the e before adding the suffix.$q$, ARRAY[$q$suffixes$q$, $q$spelling rules$q$]::text[], ARRAY[$q$RF.2.3E$q$, $q$L.2.2D$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Silent e with suffixes (raked, hiking).$q$, '', ARRAY[$q$RF.2.3E$q$, $q$L.2.2D$q$]::text[], ARRAY[$q$suffixes$q$, $q$spelling rules$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 46, $q$Vowel Teams · Contractions$q$, $q$Two words combined and shortened to make one word, joined with an apostrophe.$q$, ARRAY[$q$contractions$q$]::text[], ARRAY[$q$L.2.2C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Contractions (can't, don't, won't, doesn't).$q$, '', ARRAY[$q$L.2.2C$q$]::text[], ARRAY[$q$contractions$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 47, $q$Vowel Teams · Long a: ai, ay$q$, $q$ai is found at the beginning or middle; ay is at the end. Vowel teams are two or more letters that together represent a vowel sound.$q$, ARRAY[$q$long a ai ay$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Long a: ai, ay (rain, stay).$q$, '', ARRAY[$q$RF.1.3C$q$, $q$RF.2.3C$q$]::text[], ARRAY[$q$long a ai ay$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: play, day, say, way, wait, says, said, they, their$q$, $q$Students will read and spell the high-frequency words play, day, say, way, wait, says, said, they, their by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 48, $q$Vowel Teams · Long e: ee, ea$q$, $q$ea and ee can be found at the beginning, middle or end, most commonly in the middle.$q$, ARRAY[$q$long e ee ea$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Long e: ee, ea (need, seat).$q$, '', ARRAY[$q$RF.1.3C$q$, $q$RF.2.3C$q$]::text[], ARRAY[$q$long e ee ea$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: green, sleep, three, need, keep, feel, feet, week, real, read, please, near, means, year, leave, eat, each$q$, $q$Students will read and spell the high-frequency words green, sleep, three, need, keep, feel, feet, week, real, read, please, near, means, year, leave, eat, each by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 49, $q$Vowel Teams · Morphology: Suffix -y$q$, $q$-y is added to nouns to make adjectives.$q$, ARRAY[$q$suffixes$q$]::text[], ARRAY[$q$RF.2.3E$q$, $q$L.2.4C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Suffix -y (windy, sunny).$q$, '', ARRAY[$q$RF.2.3E$q$, $q$L.2.4C$q$]::text[], ARRAY[$q$suffixes$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 50, $q$Vowel Teams · Long o: oa, ow, oe$q$, $q$oa is found at the beginning or middle; ow at the end (except shown, grown, own); oe at the end of a few words.$q$, ARRAY[$q$long o oa ow$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Long o: oa, ow, oe (boat, slow, toe).$q$, '', ARRAY[$q$RF.1.3C$q$, $q$RF.2.3C$q$]::text[], ARRAY[$q$long o oa ow$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: grow, show, goes, own, know; irregular: though$q$, $q$Students will read and spell the high-frequency words grow, show, goes, own, know; irregular: though by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 51, $q$Vowel Teams · Long i: igh, ie$q$, $q$igh is usually in the middle followed by t, and at the end of a few words (high, thigh, sigh). ie is found at the end of a few words (pie, tie, lie, die).$q$, ARRAY[$q$long i igh y$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3C$q$, $q$RF.2.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Long i: igh, ie (light, pie).$q$, '', ARRAY[$q$RF.1.3C$q$, $q$RF.2.3C$q$]::text[], ARRAY[$q$long i igh y$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: high, might, light, right, night; irregular: eye, buy$q$, $q$Students will read and spell the high-frequency words high, might, light, right, night; irregular: eye, buy by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 52, $q$Vowel Teams · Morphology: -ful, -less, -ly, -ness$q$, $q$-ful and -less make adjectives; -ly usually makes adverbs; -ness makes nouns.$q$, ARRAY[$q$suffixes$q$]::text[], ARRAY[$q$RF.2.3E$q$, $q$L.2.4C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: -ful, -less, -ly, -ness (helpful, useless, quickly, quickness).$q$, '', ARRAY[$q$RF.2.3E$q$, $q$L.2.4C$q$]::text[], ARRAY[$q$suffixes$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 53, $q$Vowel Teams · Long e: ie; other sounds of ea$q$, $q$Vowel Teams.$q$, ARRAY[$q$long e ee ea$q$]::text[], ARRAY[$q$RF.2.3C$q$, $q$RF.2.3F$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Long e: ie; other sounds of ea (field; bread, great).$q$, '', ARRAY[$q$RF.2.3C$q$, $q$RF.2.3F$q$]::text[], ARRAY[$q$long e ee ea$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 54, $q$Vowel Teams · Morphology: Prefixes re-, un-$q$, $q$re- means again or back; un- means not or the opposite of.$q$, ARRAY[$q$prefixes$q$]::text[], ARRAY[$q$RF.2.3E$q$, $q$L.2.4B$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Prefixes re-, un- (reread, unpaid).$q$, '', ARRAY[$q$RF.2.3E$q$, $q$L.2.4B$q$]::text[], ARRAY[$q$prefixes$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 55, $q$Silent Letters · Digraphs: kn, wr$q$, $q$kn and wr are digraphs with a silent letter; long ago they were blends. Words with kn often relate to sharp points, and wr to bending or twisting.$q$, ARRAY[$q$silent letters$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3F$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Digraphs: kn, wr (knot, wrist).$q$, '', ARRAY[$q$RF.2.3F$q$]::text[], ARRAY[$q$silent letters$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: know, knew, write, wrote$q$, $q$Students will read and spell the high-frequency words know, knew, write, wrote by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 56, $q$R-Controlled · <ar>$q$, $q$When a vowel is in front of r, it does not represent one of its usual sounds; it makes a new sound with the r.$q$, ARRAY[$q$r-controlled vowels$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3B$q$, $q$RF.2.3F$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern <ar> (star, card).$q$, '', ARRAY[$q$RF.1.3B$q$, $q$RF.2.3F$q$]::text[], ARRAY[$q$r-controlled vowels$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: start, part, hard, are$q$, $q$Students will read and spell the high-frequency words start, part, hard, are by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 57, $q$R-Controlled · <or>$q$, $q$When a vowel is in front of r, it does not represent one of its usual sounds; it makes a new sound with the r.$q$, ARRAY[$q$r-controlled vowels$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3B$q$, $q$RF.2.3F$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
