  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: for, or, your, four$q$, $q$Students will read and spell the high-frequency words for, or, your, four by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 58, $q$R-Controlled · <ir>, <er>, <ur> = /er/$q$, $q$The /er/ sound is usually spelled er, ir or ur.$q$, ARRAY[$q$r-controlled vowels$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3B$q$, $q$RF.2.3F$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern <ir>, <er>, <ur> = /er/ (bird, curb, fern).$q$, '', ARRAY[$q$RF.1.3B$q$, $q$RF.2.3F$q$]::text[], ARRAY[$q$r-controlled vowels$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: first, her, turn, girl, were$q$, $q$Students will read and spell the high-frequency words first, her, turn, girl, were by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 59, $q$R-Controlled · Morphology: Suffixes -er and -est$q$, $q$-er has two meanings: more than, and a person who. -est means most.$q$, ARRAY[$q$suffixes$q$]::text[], ARRAY[$q$RF.2.3E$q$, $q$L.2.4C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Suffixes -er and -est.$q$, '', ARRAY[$q$RF.2.3E$q$, $q$L.2.4C$q$]::text[], ARRAY[$q$suffixes$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 60, $q$R-Controlled · war, wor$q$, $q$The letter w often warps the sound of the following vowel: war spells /wor/ and wor spells /wer/.$q$, ARRAY[$q$r-controlled vowels$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3F$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern war, wor (warm, work).$q$, '', ARRAY[$q$RF.2.3F$q$]::text[], ARRAY[$q$r-controlled vowels$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: warm, world, work, word$q$, $q$Students will read and spell the high-frequency words warm, world, work, word by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 61, $q$R-Controlled · Morphology: Suffix -en$q$, $q$R-Controlled.$q$, ARRAY[$q$suffixes$q$]::text[], ARRAY[$q$RF.2.3E$q$, $q$L.2.4C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Morphology: Suffix -en.$q$, '', ARRAY[$q$RF.2.3E$q$, $q$L.2.4C$q$]::text[], ARRAY[$q$suffixes$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 62, $q$Other Vowels · /ū/: oo$q$, $q$There are two long u sounds, /ū/ and /yū/. /ū/ can be spelled oo, ew (usually at the end), ue (usually at the end) and ui (the rarest).$q$, ARRAY[$q$vowel teams$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
