  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: too, soon$q$, $q$Students will read and spell the high-frequency words too, soon by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 63, $q$Other Vowels · /ū/ and /yū/: ew, ui, ue$q$, $q$/yū/ is usually spelled ue or ew.$q$, ARRAY[$q$vowel teams$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
