  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 64, $q$Other Vowels · Short /oo/ (as in book)$q$, $q$The letters oo can also represent the short /oo/ sound.$q$, ARRAY[$q$vowel teams$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3C$q$, $q$RF.2.3F$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
