  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: good, look; irregular: could, would, should$q$, $q$Students will read and spell the high-frequency words good, look; irregular: could, would, should by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 65, $q$Other Vowels · /ou/ = <ou> and <ow>$q$, $q$ou: beginning or middle of a word. ow: at the end, or in the beginning or middle if followed by a single l or n.$q$, ARRAY[$q$diphthongs$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
