  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 67, $q$Other Vowels · /oi/: <oy> and <oi>$q$, $q$oi is found at the beginning or middle; oy at the end.$q$, ARRAY[$q$diphthongs$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
