  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 68, $q$Other Vowels · <aw> and <au>$q$, $q$au: beginning or middle of a word; aw: at the end, or in the beginning or middle if followed by a single l, n or k.$q$, ARRAY[$q$vowel teams$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3C$q$, $q$RF.2.3F$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
