  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 70, $q$Multisyllable & Morphology · Digraphs & ghost sounds: ph, gn, mb$q$, $q$Multisyllable & Morphology.$q$, ARRAY[$q$silent letters$q$]::text[], ARRAY[$q$RF.2.3F$q$, $q$RF.3.3C$q$]::text[], 1, 'claude') RETURNING id INTO u;
