  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 71, $q$Multisyllable & Morphology · Compound Words$q$, $q$A word made up of two smaller words.$q$, ARRAY[$q$compound words$q$]::text[], ARRAY[$q$L.2.4D$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Compound Words (sunset, sandbox).$q$, '', ARRAY[$q$L.2.4D$q$]::text[], ARRAY[$q$compound words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 72, $q$Multisyllable & Morphology · VCCV Words (closed-closed)$q$, $q$When you see the pattern VCCV, usually divide the word between the two consonants. The first vowel will be short.$q$, ARRAY[$q$syllables$q$, $q$syllable division$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.1.3E$q$, $q$RF.2.3D$q$, $q$RF.3.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern VCCV Words (closed-closed) (bas-ket, rab-bit).$q$, '', ARRAY[$q$RF.1.3E$q$, $q$RF.2.3D$q$, $q$RF.3.3C$q$]::text[], ARRAY[$q$syllables$q$, $q$syllable division$q$]::text[], 'claude');
