  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 73, $q$Multisyllable & Morphology · The Schwa$q$, $q$The schwa is the most common vowel sound. Every vowel can represent it. It is a lazy /ŭ/ or /ĭ/ sound.$q$, ARRAY[$q$schwa$q$]::text[], ARRAY[$q$RF.3.3C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern The Schwa (bacon, data, nickel).$q$, '', ARRAY[$q$RF.3.3C$q$]::text[], ARRAY[$q$schwa$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 74, $q$Multisyllable & Morphology · Y spells /ē/ & review Suffix -y$q$, $q$At the end of multi-syllable words, y says /ē/.$q$, ARRAY[$q$long e y$q$, $q$suffixes$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3C$q$, $q$RF.2.3E$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern Y spells /ē/ & review Suffix -y (funny, bumpy).$q$, '', ARRAY[$q$RF.2.3C$q$, $q$RF.2.3E$q$]::text[], ARRAY[$q$long e y$q$, $q$suffixes$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: only, carry, funny, pretty$q$, $q$Students will read and spell the high-frequency words only, carry, funny, pretty by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 75, $q$Multisyllable & Morphology · VCCCV Syllable Division Rule (closed-closed)$q$, $q$Usually divide after the first consonant, unless you need to keep digraphs and blends together, as in pump-kin.$q$, ARRAY[$q$syllable division$q$]::text[], ARRAY[$q$RF.3.3C$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern VCCCV Syllable Division Rule (closed-closed) (conflict, pumpkin).$q$, '', ARRAY[$q$RF.3.3C$q$]::text[], ARRAY[$q$syllable division$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 76, $q$Multisyllable & Morphology · VCV Words (V-CV and VC-V)$q$, $q$Sometimes divide after the first vowel, which makes it long; other times after the consonant, which makes it short.$q$, ARRAY[$q$syllable division$q$, $q$open syllables$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3D$q$, $q$RF.3.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 1, $q$Teach the pattern$q$, $q$Students will read and spell words with the pattern VCV Words (V-CV and VC-V) (ro-bot, clos-et).$q$, '', ARRAY[$q$RF.2.3D$q$, $q$RF.3.3C$q$]::text[], ARRAY[$q$syllable division$q$, $q$open syllables$q$]::text[], 'claude');
  INSERT INTO curriculum_lessons (unit_id, sort_order, title, objective, notes, ccss_codes, skill_tags, source) VALUES (u, 2, $q$High-frequency words: even, open, seven, very, any, many, ago, along$q$, $q$Students will read and spell the high-frequency words even, open, seven, very, any, many, ago, along by sight.$q$, '', ARRAY[$q$RF.2.3G$q$]::text[], ARRAY[$q$sight words$q$]::text[], 'claude');
  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 77, $q$Multisyllable & Morphology · Soft c and Soft G$q$, $q$c spells /s/ and g spells /j/ when e, i or y follows.$q$, ARRAY[$q$soft c and g$q$]::text[], ARRAY[$q$RF.2.3F$q$, $q$RF.3.3C$q$]::text[], 1, 'claude') RETURNING id INTO u;
