  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 78, $q$Multisyllable & Morphology · Consonant -le$q$, $q$A syllable type that is always at the end of the word, the only one where you do not hear a distinct vowel sound. Divide right before the consonant.$q$, ARRAY[$q$syllables$q$, $q$syllable division$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.3.3C$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
