  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 79, $q$Multisyllable & Morphology · 2-Syllable Words with silent e$q$, $q$Multisyllable & Morphology.$q$, ARRAY[$q$long a vce$q$, $q$syllable division$q$, $q$sight words$q$]::text[], ARRAY[$q$RF.2.3D$q$, $q$RF.2.3G$q$]::text[], 1, 'claude') RETURNING id INTO u;
