  INSERT INTO curriculum_units (book_id, sort_order, title, summary, skill_tags, ccss_codes, default_weeks, source) VALUES (b, 80, $q$Multisyllable & Morphology · Morphology: Suffix -ive and -ion$q$, $q$-ive means doing or being and makes adjectives. -ion means action or process of and forms abstract nouns; with t it makes the final stable syllable tion, /shun/.$q$, ARRAY[$q$suffixes$q$]::text[], ARRAY[$q$RF.3.3A$q$, $q$RF.3.3B$q$, $q$L.3.4B$q$]::text[], 1, 'claude') RETURNING id INTO u;
